196	          trackReadReceipts: TimelineReadReceiptTracking.AllEvents,
197	          reportUtds: false,
198	        });
199	
200	        // Store timeline in ref for reuse in pagination
201	        timelineRef.current = timeline;
202	
203	        // Set up listener BEFORE paginateBackwards so the SDK's initial
204	        // cached diffs (from SQLite) are received immediately — no network needed.
205	        // Set up timeline listener for real-time updates
206	        timelineListenerHandle = await timeline.addListener({
207	          onUpdate: (diffs) => {
208	            const beforeCount = timelineItemsRef.current.length;
209	            diffs.forEach((diff) => {
210	              const change = diff.tag;
211	              const timelineItems = timelineItemsRef.current;
212	              switch (change) {
213	                case TimelineDiff_Tags.Append: {
214	                  if (diff.inner.values.length > 0) {
215	                    timelineItems.push(...diff.inner.values.map(toEventItem));
216	                  }
217	                  break;
218	                }
219	                case TimelineDiff_Tags.Insert: {
220	                  const { index, value } = diff.inner;
221	                  timelineItems.splice(index, 0, toEventItem(value));
222	                  break;
223	                }
224	                case TimelineDiff_Tags.Set: {
225	                  const { index, value } = diff.inner;
226	                  const ev = toEventItem(value);
227	                  timelineItems[index] = ev;
228	
229	                  // transactionId -> eventId transition can arrive in an order where
230	                  // a stale local echo still exists elsewhere in the list.
231	                  if (
232	                    ev?.isOwn &&
233	                    !ev.localSendState &&
234	                    pendingTransactionIdsQueue.current.length > 0
235	                  ) {
236	                    const txId = pendingTransactionIdsQueue.current.shift();
237	                    if (txId) {
238	                      const txIndex = timelineItems.findIndex((item) => {
239	                        if (!item) return false;
240	                        return getItemUniqueKey(item) === txId;
241	                      });
242	                      if (txIndex !== -1) {
243	                        timelineItems[txIndex] = ev;
244	                      }
245	                    }
246	                  }
247	                  break;
248	                }
249	                case TimelineDiff_Tags.Remove: {
250	                  const { index: removeIndex } = diff.inner;
251	                  if (removeIndex >= 0 && removeIndex < timelineItems.length) {
252	                    timelineItems.splice(removeIndex, 1);
253	                  }
254	                  break;
255	                }
256	                case TimelineDiff_Tags.PushFront: {
257	                  const { value } = diff.inner;
258	                  timelineItems.unshift(toEventItem(value));
259	                  break;
260	                }
261	                case TimelineDiff_Tags.PushBack: {
262	                  const { value } = diff.inner;
263	                  const ev = toEventItem(value);
264	                  timelineItems.push(ev);
265	                  if (ev) {
266	                    const txId = getTransactionId(ev);
267	                    if (txId) {
268	                      pendingTransactionIdsQueue.current.push(txId);
269	                    }
270	                  }
271	                  break;
272	                }
273	                case TimelineDiff_Tags.PopFront: {
274	                  timelineItems.shift();
275	                  break;
276	                }
277	                case TimelineDiff_Tags.PopBack: {
278	                  timelineItems.pop();
279	                  break;
280	                }
281	                case TimelineDiff_Tags.Reset: {
282	                  const resetItems = diff.inner.values;
283	                  pendingTransactionIdsQueue.current = [];
284	                  timelineItemsRef.current = resetItems.map(toEventItem);
285	
286	                  const eventItems = timelineItemsRef.current.filter(
287	                    (i): i is EventTimelineItem => !!i,
288	                  );
289	                  pendingTransactionIdsQueue.current = eventItems
290	                    .map(getTransactionId)
291	                    .filter((id): id is string => !!id);
292	                  break;
293	                }
294	                case TimelineDiff_Tags.Truncate: {
295	                  const { length: cut } = diff.inner;
296	                  timelineItems.length = cut;
297	                  break;
298	                }
299	                case TimelineDiff_Tags.Clear: {
300	                  timelineItemsRef.current = [];
301	                  pendingTransactionIdsQueue.current = [];
302	                  eventIdsRef.current = new Set();
303	                  setEvents([]);
304	                  break;
305	                }
306	                default:
307	                  console.log("Unknown timeline change type:", change);
308	              }
309	            });
310	
311	            if (diffs.some((diff) => diff.tag !== TimelineDiff_Tags.Clear)) {
312	              if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
313	              rebuildTimerRef.current = setTimeout(
314	                rebuildEventsFromTimelineItems,
315	                0,
316	              );
317	            }
318	
319	            if (ENABLE_TIMELINE_DEBUG) {
320	              const afterCount = timelineItemsRef.current.length;
321	              const tags = diffs.map((d) => d.tag).join(", ");
322	              console.log(
323	                `[TimelineDebug][${roomId}] diffs=[${tags}] items ${beforeCount}->${afterCount}`,
324	              );
325	            }
326	
327	          },
328	        });
329	
330	        // Paginate after the listener is set up so events flow through it.
331	        // Loop until we have at least MIN_INITIAL_EVENTS or reach the start.
332	        isPaginatingRef.current = true;
333	        (async () => {
334	          try {
335	            let hitStart = false;
336	            while (!isDisposed && !hitStart) {
337	              hitStart = await timeline.paginateBackwards(TIMELINE_PAGE_SIZE);
338	              if (hitStart) {
339	                reachedStartRef.current = true;
340	                break;
341	              }
342	              const eventCount = timelineItemsRef.current.filter(Boolean).length;
343	              if (eventCount >= MIN_INITIAL_EVENTS) break;
344	            }
345	          } catch (error) {
346	            if (!isDisposed) {
347	              console.warn("Failed to load initial messages:", error);
348	            }
349	          } finally {
350	            isPaginatingRef.current = false;
351	          }
352	        })();
353	      } catch (error) {
354	        console.error("Failed to initialize room timeline:", error);
355	        offlineToastHelper("Failed to load the messages. Please try again.");
356	        NavigationContainerRef.goBack();
357	        return null;
358	      }
359	    };
360	
361	    initRoomTimeline();
362	
363	    return () => {
364	      isDisposed = true;
365	      timelineListenerHandle?.cancel?.();
366	      if (rebuildTimerRef.current) clearTimeout(rebuildTimerRef.current);
367	      timelineRef.current = null;
368	      timelineItemsRef.current = [];
369	      isPaginatingRef.current = false;
370	      reachedStartRef.current = false;
371	    };
