1	import type {
2	  EventTimelineItem,
3	  RoomInterface,
4	  TaskHandleInterface,
5	  TimelineInterface,
6	} from "@unomed/react-native-matrix-sdk";
7	import {
8	  DateDividerMode,
9	  RoomMessageEventMessageType,
10	  TimelineDiff_Tags,
11	  TimelineFilter,
12	  TimelineFocus,
13	  TimelineReadReceiptTracking,
14	} from "@unomed/react-native-matrix-sdk";
15	import { getEventId } from "modules/matrix-client/utils";
16	import { useCallback, useEffect, useRef, useState } from "react";
17	
18	//TODO: Make a timeline module
19	
20	interface UseMediaTimelineProps {
21	  room: RoomInterface | undefined;
22	  roomId: string;
23	}
24	
25	export const useMediaTimeline = ({ room, roomId }: UseMediaTimelineProps) => {
26	  const [mediaItems, setMediaItems] = useState<EventTimelineItem[]>([]);
27	  const [loading, setLoading] = useState(true);
28	  const eventIdsRef = useRef<Set<string>>(new Set());
29	  const timelineRef = useRef<TimelineInterface | null>(null);
30	
31	  const upsertMediaItems = useCallback((incoming: EventTimelineItem[]) => {
32	    setMediaItems((prev) => {
33	      const next = [...prev];
34	      for (const event of incoming) {
35	        const id = getEventId(event);
36	        if (!id || eventIdsRef.current.has(id)) continue;
37	
38	        eventIdsRef.current.add(id);
39	        next.push(event);
40	      }
41	      return next.sort((a, b) => Number(b.timestamp) - Number(a.timestamp));
42	    });
43	  }, []);
44	
45	  useEffect(() => {
46	    if (!room) return;
47	
48	    setLoading(true);
49	    setMediaItems([]);
50	    eventIdsRef.current.clear();
51	
52	    let timelineListenerHandle: TaskHandleInterface | null = null;
53	
54	    const initMediaTimeline = async () => {
55	      try {
56	        const timeline = await room.timelineWithConfiguration({
57	          focus: new TimelineFocus.Live({ hideThreadedEvents: false }),
58	          filter: new TimelineFilter.OnlyMessage({
59	            types: [
60	              RoomMessageEventMessageType.Image,
61	              RoomMessageEventMessageType.Video,
62	              RoomMessageEventMessageType.File,
63	              RoomMessageEventMessageType.Audio,
64	            ],
65	          }),
66	          internalIdPrefix: "media_",
67	          dateDividerMode: DateDividerMode.Daily,
68	          trackReadReceipts: TimelineReadReceiptTracking.Disabled,
69	          reportUtds: false,
70	        });
71	
72	        timelineRef.current = timeline;
73	
74	        // Set up timeline listener for updates
75	        timelineListenerHandle = await timeline.addListener({
76	          onUpdate: (diffs) => {
77	            diffs.forEach((diff) => {
78	              const change = diff.tag;
79	              switch (change) {
80	                case TimelineDiff_Tags.Append: {
81	                  const newItems = diff.inner.values;
82	                  if (newItems.length) {
83	                    const eventItems = newItems
84	                      .map((i) => i.asEvent())
85	                      .filter((i): i is EventTimelineItem => !!i);
86	                    if (eventItems.length > 0) upsertMediaItems(eventItems);
87	                  }
88	                  break;
89	                }
90	                case TimelineDiff_Tags.Insert:
91	                case TimelineDiff_Tags.PushFront:
92	                case TimelineDiff_Tags.PushBack: {
93	                  const { value } = diff.inner;
94	                  const ev = value.asEvent();
95	                  if (ev) upsertMediaItems([ev]);
96	                  break;
97	                }
98	                case TimelineDiff_Tags.Set: {
99	                  const { value } = diff.inner;
100	                  const ev = value.asEvent();
101	                  if (ev) {
102	                    const id = getEventId(ev);
103	                    if (!id) break;
104	
105	                    setMediaItems((prev) => {
106	                      const existingIndex = prev.findIndex(
107	                        (item) => getEventId(item) === id,
108	                      );
109	                      if (existingIndex >= 0) {
110	                        const next = [...prev];
111	                        next[existingIndex] = ev;
112	                        return next;
113	                      }
114	                      return prev;
115	                    });
116	                  }
117	                  break;
118	                }
119	                case TimelineDiff_Tags.Remove: {
120	                  const { index: removeIndex } = diff.inner;
121	                  setMediaItems((prev) => {
122	                    const next = prev.filter((_, idx) => idx !== removeIndex);
123	                    eventIdsRef.current = new Set(
124	                      next
125	                        .map((item) => getEventId(item))
126	                        .filter(Boolean) as string[],
127	                    );
128	                    return next;
129	                  });
130	                  break;
131	                }
132	                case TimelineDiff_Tags.Reset: {
133	                  const resetItems = diff.inner.values;
134	                  if (resetItems.length) {
135	                    const eventItems = resetItems
136	                      .map((i) => i.asEvent())
137	                      .filter((i): i is EventTimelineItem => !!i);
138	
139	                    const seenIds = new Set<string>();
140	                    const newMediaItems: EventTimelineItem[] = [];
141	
142	                    for (const event of eventItems) {
143	                      const id = getEventId(event);
144	                      if (id && !seenIds.has(id)) {
145	                        seenIds.add(id);
146	                        newMediaItems.push(event);
147	                      }
148	                    }
149	
150	                    eventIdsRef.current = seenIds;
151	                    setMediaItems(
152	                      newMediaItems.sort(
153	                        (a, b) => Number(b.timestamp) - Number(a.timestamp),
154	                      ),
155	                    );
156	                  }
157	                  break;
158	                }
159	                case TimelineDiff_Tags.Clear: {
160	                  eventIdsRef.current.clear();
161	                  setMediaItems([]);
162	                  break;
163	                }
164	                default:
165	                  break;
166	              }
167	            });
168	          },
169	        });
170	
171	        // Paginate backwards until we reach the start of the timeline
172	        let reachedStart = false;
173	        while (!reachedStart) {
174	          reachedStart = await timeline.paginateBackwards(100);
175	        }
176	
177	        setLoading(false);
178	      } catch (error) {
179	        console.error("Failed to initialize media timeline:", error);
180	        setLoading(false);
181	      }
182	    };
183	
184	    initMediaTimeline();
185	
186	    return () => {
187	      timelineListenerHandle?.cancel?.();
