1	import type { RoomInfo, RoomInterface } from "@unomed/react-native-matrix-sdk";
2	import { useEffect, useState } from "react";
3	
4	export const useRoomInfo = (room: RoomInterface | undefined) => {
5	  const [roomInfo, setRoomInfo] = useState<RoomInfo | null>(null);
6	
7	  useEffect(() => {
8	    if (!room) return;
9	    room.roomInfo().then(setRoomInfo).catch(console.error);
10	    const handle = room.subscribeToRoomInfoUpdates({ call: setRoomInfo });
11	    return () => handle.cancel();
12	  }, [room]);
13	
14	  return roomInfo;
15	};
