import { Block, Text } from "@prototyp/skeletor";
import type { EventTimelineItem } from "@unomed/react-native-matrix-sdk";
import {
  MessageType_Tags,
  MsgLikeKind_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import type { FC } from "react";
import { Image, StyleSheet } from "react-native";
import { Button } from "shared/components";
import { Colors, TextSize } from "shared/styles";

const getPreviewText = (event: EventTimelineItem): string => {
  if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return "Message";
  const kind = event.content.inner.content.kind;
  if (kind?.tag !== MsgLikeKind_Tags.Message) return "Message";
  const msgType = kind.inner.content.msgType;
  if (!msgType) return "Message";
  switch (msgType.tag) {
    case MessageType_Tags.Text:
    case MessageType_Tags.Notice:
      return msgType.inner.content.body;
    case MessageType_Tags.Image:
      return "Photo";
    case MessageType_Tags.Video:
      return "Video";
    case MessageType_Tags.Audio:
      return "Voice message";
    case MessageType_Tags.File:
      return msgType.inner.content.body || "File";
    default:
      return "Message";
  }
};

interface Props {
  events: EventTimelineItem[];
  selectedIndex: number;
  onTap: () => void;
  onViewAll: () => void;
}

export const PinnedEventsBanner: FC<Props> = ({
  events,
  selectedIndex,
  onTap,
  onViewAll,
}) => {
  const currentEvent = events[selectedIndex];
  if (!currentEvent) return null;

  const preview = getPreviewText(currentEvent);
  const total = events.length;

  return (
    <Block
      flexDirection="row"
      align="center"
      background={Colors.blackMinus3}
      paddings={[10, 16]}
      gap={12}
      border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
    >
      <Image
        source={require("assets/icons/pin.png")}
        style={styles.pinIcon}
        tintColor={Colors.primary}
      />

      <Button.Wrapper onPress={onTap} style={styles.centerContent}>
        <Block gap={2} style={styles.centerContent}>
          <Text size={TextSize.small} color={Colors.white50}>
            {selectedIndex + 1} / {total}
          </Text>
          <Text numberOfLines={1} size={TextSize.small}>
            {preview}
          </Text>
        </Block>
      </Button.Wrapper>

      <Button.Wrapper onPress={onViewAll}>
        <Text size={TextSize.small} color={Colors.primary}>
          View all
        </Text>
      </Button.Wrapper>
    </Block>
  );
};

const styles = StyleSheet.create({
  pinIcon: {
    width: 16,
    height: 16,
  },
  centerContent: {
    flex: 1,
  },
});

